from __future__ import annotations

from dataclasses import dataclass, field, replace

from .plant import PlantInputs


@dataclass(frozen=True)
class SafetyConfig:
    # Synthetic benchmark thresholds, not engineered SIL set points.
    cstr_temperature_hh_K: float = 348.0
    cstr_pressure_hh_bar: float = 4.00
    cstr_pressure_hhh_bar: float = 4.35
    cstr_level_hh_kmol: float = 72.0   # about 90% of the 6 m3 vessel volume
    cstr_level_ll_kmol: float = 20.0   # about 25% vessel fill

    reboiler_level_ll_kmol: float = 12.08
    reboiler_level_hh_kmol: float = 51.76
    drum_level_ll_kmol: float = 10.59
    drum_level_hh_kmol: float = 45.37
    column_pressure_hh_bar: float = 1.35

    max_emergency_cooling_factor: float = 1.0
    max_condenser_cooling_valve: float = 1.0
    pressure_escalation_feed_fraction: float = 0.40
    reset_hysteresis_fraction: float = 0.05


@dataclass
class SafetyResult:
    commanded: PlantInputs
    active_causes: tuple[str, ...]
    latched_causes: tuple[str, ...]
    plant_trip_latched: bool
    cause_flags: dict[str, bool] = field(default_factory=dict)


class SafetySystem:
    """Independent deterministic SIF/interrupt layer.

    It receives independent safety measurements (currently noise-free copies of
    physical states), latches trips, and overrides requested commands.  Final
    element faults are applied *after* this layer by the actuator-fault engine.
    """

    CAUSES = (
        "R_T_HH",
        "R_P_HH",
        "R_P_HHH",
        "R_L_HH",
        "R_L_LL",
        "RB_L_LL",
        "RB_L_HH",
        "DR_L_LL",
        "DR_L_HH",
        "COL_P_HH",
    )

    def __init__(self, config: SafetyConfig = SafetyConfig()):
        self.cfg = config
        self.latched: dict[str, bool] = {k: False for k in self.CAUSES}
        self.plant_trip_latched = False

    def reset(self) -> None:
        for k in self.latched:
            self.latched[k] = False
        self.plant_trip_latched = False

    def _instantaneous_flags(self, m: dict[str, float]) -> dict[str, bool]:
        c = self.cfg
        return {
            "R_T_HH": m["cstr_temperature_K"] >= c.cstr_temperature_hh_K,
            "R_P_HH": m["cstr_pressure_bar"] >= c.cstr_pressure_hh_bar,
            "R_P_HHH": m["cstr_pressure_bar"] >= c.cstr_pressure_hhh_bar,
            "R_L_HH": m["cstr_holdup_kmol"] >= c.cstr_level_hh_kmol,
            "R_L_LL": m["cstr_holdup_kmol"] <= c.cstr_level_ll_kmol,
            "RB_L_LL": m["reboiler_holdup_kmol"] <= c.reboiler_level_ll_kmol,
            "RB_L_HH": m["reboiler_holdup_kmol"] >= c.reboiler_level_hh_kmol,
            "DR_L_LL": m["drum_holdup_kmol"] <= c.drum_level_ll_kmol,
            "DR_L_HH": m["drum_holdup_kmol"] >= c.drum_level_hh_kmol,
            "COL_P_HH": m["column_pressure_bar"] >= c.column_pressure_hh_bar,
        }

    def _safe_to_reset(self, cause: str, m: dict[str, float]) -> bool:
        h = self.cfg.reset_hysteresis_fraction
        c = self.cfg
        if cause == "R_T_HH":
            return m["cstr_temperature_K"] < c.cstr_temperature_hh_K * (1.0 - h)
        if cause == "R_P_HH":
            return m["cstr_pressure_bar"] < c.cstr_pressure_hh_bar * (1.0 - h)
        if cause == "R_P_HHH":
            return m["cstr_pressure_bar"] < c.cstr_pressure_hhh_bar * (1.0 - h)
        if cause == "R_L_HH":
            return m["cstr_holdup_kmol"] < c.cstr_level_hh_kmol * (1.0 - h)
        if cause == "R_L_LL":
            return m["cstr_holdup_kmol"] > c.cstr_level_ll_kmol * (1.0 + h)
        if cause == "RB_L_HH":
            return m["reboiler_holdup_kmol"] < c.reboiler_level_hh_kmol * (1.0 - h)
        if cause == "RB_L_LL":
            return m["reboiler_holdup_kmol"] > c.reboiler_level_ll_kmol * (1.0 + h)
        if cause == "DR_L_HH":
            return m["drum_holdup_kmol"] < c.drum_level_hh_kmol * (1.0 - h)
        if cause == "DR_L_LL":
            return m["drum_holdup_kmol"] > c.drum_level_ll_kmol * (1.0 + h)
        if cause == "COL_P_HH":
            return m["column_pressure_bar"] < c.column_pressure_hh_bar * (1.0 - h)
        return False

    def apply(
        self,
        measurements: dict[str, float],
        requested: PlantInputs,
        nominal: PlantInputs,
        reset_requested: bool = False,
    ) -> SafetyResult:
        flags = self._instantaneous_flags(measurements)

        if reset_requested:
            for cause in self.CAUSES:
                if self.latched[cause] and self._safe_to_reset(cause, measurements):
                    self.latched[cause] = False
            if not any(self.latched[c] for c in ("R_P_HHH", "RB_L_HH", "DR_L_LL", "DR_L_HH", "COL_P_HH")):
                self.plant_trip_latched = False

        for cause, active in flags.items():
            if active:
                self.latched[cause] = True

        # Severe escalations define a process trip state, but individual SIF
        # activation is not by itself an episode-termination condition.
        if any(self.latched[c] for c in ("R_P_HHH", "RB_L_HH", "DR_L_LL", "DR_L_HH", "COL_P_HH")):
            self.plant_trip_latched = True

        u = requested

        # Reactor T-HH: remove external heat, retain feed, add emergency cooling.
        if self.latched["R_T_HH"]:
            u = replace(
                u,
                cstr_heater_factor=0.0,
                cstr_emergency_cooling_factor=max(u.cstr_emergency_cooling_factor, self.cfg.max_emergency_cooling_factor),
            )

        # First pressure stage: maximize H2 removal, do not cut feed.
        if self.latched["R_P_HH"]:
            u = replace(
                u,
                cstr_heater_factor=0.0,
                cstr_vent_valve=1.0,
                cstr_bdv_valve=1.0,
            )

        # Escalated pressure: preserve the same protection and reduce, rather
        # than immediately isolate, feed because the benchmark reaction is endothermic.
        if self.latched["R_P_HHH"]:
            u = replace(
                u,
                fresh_ipa_feed=min(u.fresh_ipa_feed, self.cfg.pressure_escalation_feed_fraction * nominal.fresh_ipa_feed),
                cstr_heater_factor=0.0,
                cstr_vent_valve=1.0,
                cstr_bdv_valve=1.0,
            )

        if self.latched["R_L_HH"]:
            u = replace(u, fresh_ipa_feed=0.0, cstr_heater_factor=0.0)

        if self.latched["R_L_LL"]:
            u = replace(u, cstr_heater_factor=0.0, cstr_outflow=0.0)

        if self.latched["RB_L_LL"]:
            u = replace(u, steam_factor=0.0, bottoms_flow=0.0)

        if self.latched["RB_L_HH"]:
            u = replace(
                u, steam_factor=0.0, cstr_outflow=0.0,
                fresh_ipa_feed=0.0, cstr_heater_factor=0.0,
            )

        if self.latched["DR_L_LL"]:
            u = replace(
                u, reflux_flow=0.0, distillate_flow=0.0, steam_factor=0.0,
                cstr_outflow=0.0, fresh_ipa_feed=0.0, cstr_heater_factor=0.0,
            )

        if self.latched["DR_L_HH"]:
            u = replace(
                u, steam_factor=0.0, cstr_outflow=0.0,
                fresh_ipa_feed=0.0, cstr_heater_factor=0.0,
            )

        if self.latched["COL_P_HH"]:
            u = replace(
                u,
                steam_factor=0.0,
                condenser_cooling_valve=max(
                    u.condenser_cooling_valve, self.cfg.max_condenser_cooling_valve
                ),
                cstr_outflow=0.0,
                fresh_ipa_feed=0.0,
                cstr_heater_factor=0.0,
            )

        return SafetyResult(
            commanded=u,
            active_causes=tuple(k for k, v in flags.items() if v),
            latched_causes=tuple(k for k, v in self.latched.items() if v),
            plant_trip_latched=bool(self.plant_trip_latched),
            cause_flags=flags,
        )

integrated_plant/scenario.py:
from __future__ import annotations

from dataclasses import dataclass, replace
from typing import Protocol, Sequence
import math
import numpy as np

from .plant import PlantInputs


class Trajectory(Protocol):
    def value(self, t_h: float) -> float: ...
    def breakpoints(self) -> list[float]: ...


@dataclass(frozen=True)
class Constant:
    c: float
    def value(self, t_h: float) -> float:
        return float(self.c)
    def breakpoints(self) -> list[float]:
        return []


@dataclass(frozen=True)
class PiecewiseConstant:
    """Right-continuous piecewise-constant trajectory."""
    points: Sequence[tuple[float, float]]

    def __post_init__(self):
        if not self.points:
            raise ValueError("PiecewiseConstant requires at least one point")
        times = [p[0] for p in self.points]
        if times != sorted(times):
            raise ValueError("PiecewiseConstant points must be sorted by time")

    def value(self, t_h: float) -> float:
        val = self.points[0][1]
        for t0, v in self.points:
            if t_h + 1e-12 >= t0:
                val = v
            else:
                break
        return float(val)

    def breakpoints(self) -> list[float]:
        return [float(t) for t, _ in self.points[1:]]


@dataclass(frozen=True)
class PiecewiseLinear:
    points: Sequence[tuple[float, float]]

    def __post_init__(self):
        if len(self.points) < 2:
            raise ValueError("PiecewiseLinear requires at least two points")
        times = [p[0] for p in self.points]
        if times != sorted(times):
            raise ValueError("PiecewiseLinear points must be sorted by time")

    def value(self, t_h: float) -> float:
        if t_h <= self.points[0][0]:
            return float(self.points[0][1])
        if t_h >= self.points[-1][0]:
            return float(self.points[-1][1])
        for (t0, v0), (t1, v1) in zip(self.points[:-1], self.points[1:]):
            if t0 <= t_h <= t1:
                f = (t_h - t0) / (t1 - t0)
                return float(v0 + f * (v1 - v0))
        return float(self.points[-1][1])

    def breakpoints(self) -> list[float]:
        return [float(t) for t, _ in self.points[1:-1]]


@dataclass(frozen=True)
class Sine:
    mean: float
    amplitude: float
    period_h: float
    phase_rad: float = 0.0
    def value(self, t_h: float) -> float:
        return float(self.mean + self.amplitude * math.sin(2.0 * math.pi * t_h / self.period_h + self.phase_rad))
    def breakpoints(self) -> list[float]:
        return []


@dataclass(frozen=True)
class ReactionRateFault:
    """Temporary catalyst/reaction-rate loss used by the legacy FDD campaign."""
    name: str
    start_h: float
    final_loss_fraction: float
    ramp_duration_h: float = 10.0 / 60.0
    full_duration_h: float = 10.0 / 60.0

    def __post_init__(self):
        if not (0.0 <= self.final_loss_fraction < 1.0):
            raise ValueError("final_loss_fraction must be in [0,1)")

    @property
    def end_h(self) -> float:
        return self.start_h + self.ramp_duration_h + self.full_duration_h

    def loss_fraction(self, t_h: float) -> float:
        if t_h < self.start_h or t_h >= self.end_h:
            return 0.0
        dt = t_h - self.start_h
        if dt < self.ramp_duration_h - 1e-12:
            return float((self.final_loss_fraction / 3.0) * dt / self.ramp_duration_h)
        return float(self.final_loss_fraction)

    def active(self, t_h: float) -> bool:
        return self.start_h <= t_h < self.end_h

    def breakpoints(self) -> list[float]:
        return [self.start_h, self.start_h + self.ramp_duration_h, self.end_h]


@dataclass(frozen=True)
class CatalystActivityTrajectory:
    faults: Sequence[ReactionRateFault]
    base_activity: float = 1.0

    def value(self, t_h: float) -> float:
        loss = max((f.loss_fraction(t_h) for f in self.faults), default=0.0)
        return float(max(0.0, self.base_activity - loss))

    def breakpoints(self) -> list[float]:
        return sorted({x for f in self.faults for x in f.breakpoints()})

    def active_faults(self, t_h: float) -> list[ReactionRateFault]:
        return [f for f in self.faults if f.active(t_h)]


@dataclass(frozen=True)
class ScenarioEvent:
    name: str
    kind: str
    target: str
    start_h: float
    end_h: float | None
    magnitude: float | None = None
    metadata: str = ""

    def active(self, t_h: float) -> bool:
        return t_h >= self.start_h and (self.end_h is None or t_h < self.end_h)


@dataclass(frozen=True)
class Scenario:
    """External scenario definition; all trajectories use simulated time."""
    duration_h: float
    throughput_fraction: Trajectory = Constant(1.0)
    feed_temperature_K: Trajectory = Constant(298.15)
    cooling_water_temperature_K: Trajectory = Constant(298.15)
    steam_pressure_bar: Trajectory = Constant(5.659806566043441)
    cstr_heating_utility_temperature_K: Trajectory = Constant(390.0)
    ambient_temperature_K: Trajectory = Constant(298.15)
    catalyst_activity: Trajectory = Constant(1.0)
    # Independent condenser utility/equipment effectiveness.  The cooling-water
    # valve itself is now a manipulated variable generated by the column PIC.
    condenser_cooling_effectiveness: Trajectory = Constant(1.0)
    condenser_pressure_bar: Trajectory = Constant(1.0)  # legacy/reference only
    cstr_liquid_leak_kmol_h: Trajectory = Constant(0.0)
    reboiler_liquid_leak_kmol_h: Trajectory = Constant(0.0)
    drum_liquid_leak_kmol_h: Trajectory = Constant(0.0)
    name: str = "scenario"
    events: tuple[ScenarioEvent, ...] = ()

    def evaluate(self, t_h: float, nominal: PlantInputs) -> PlantInputs:
        return replace(
            nominal,
            fresh_ipa_feed=nominal.fresh_ipa_feed * self.throughput_fraction.value(t_h),
            fresh_feed_temperature_K=self.feed_temperature_K.value(t_h),
            cooling_water_temperature_K=self.cooling_water_temperature_K.value(t_h),
            steam_pressure_bar=self.steam_pressure_bar.value(t_h),
            cstr_heating_utility_temperature_K=self.cstr_heating_utility_temperature_K.value(t_h),
            ambient_temperature_K=self.ambient_temperature_K.value(t_h),
            catalyst_activity=self.catalyst_activity.value(t_h),
            condenser_cooling_effectiveness=self.condenser_cooling_effectiveness.value(t_h),
            condenser_pressure_bar=self.condenser_pressure_bar.value(t_h),
            cstr_liquid_leak_kmol_h=self.cstr_liquid_leak_kmol_h.value(t_h),
            reboiler_liquid_leak_kmol_h=self.reboiler_liquid_leak_kmol_h.value(t_h),
            drum_liquid_leak_kmol_h=self.drum_liquid_leak_kmol_h.value(t_h),
        )

    def breakpoints(self) -> list[float]:
        fields = [
            self.throughput_fraction,
            self.feed_temperature_K,
            self.cooling_water_temperature_K,
            self.steam_pressure_bar,
            self.cstr_heating_utility_temperature_K,
            self.ambient_temperature_K,
            self.catalyst_activity,
            self.condenser_cooling_effectiveness,
            self.condenser_pressure_bar,
            self.cstr_liquid_leak_kmol_h,
            self.reboiler_liquid_leak_kmol_h,
            self.drum_liquid_leak_kmol_h,
        ]
        return sorted({x for tr in fields for x in tr.breakpoints() if 0.0 < x < self.duration_h})

    def active_events(self, t_h: float) -> list[ScenarioEvent]:
        return [e for e in self.events if e.active(t_h)]


def nominal_hold_scenario(duration_min: float = 180.0) -> Scenario:
    """Constant 100% production.  Only the measurement layer adds sensor noise."""
    return Scenario(duration_h=float(duration_min) / 60.0, name="nominal_hold")


def _pulse(nominal: float, start_h: float, duration_h: float, multiplier: float) -> PiecewiseConstant:
    return PiecewiseConstant([
        (0.0, nominal),
        (float(start_h), nominal * multiplier),
        (float(start_h + duration_h), nominal),
    ])


# Size of one "normal" disturbance step. Temperatures are stepped in kelvin (additive)
# and pressures as a fraction of nominal. Before 2026-10-05 every variable was scaled by
# +/-10 %, which on absolute temperatures meant +/-30-39 K (cooling water at 55 degC):
# a severe upset rather than normal variability.
DISTURBANCE_STEPS: dict[str, tuple[str, float]] = {
    "feed_temperature_K": ("add", 5.0),
    "fresh_feed_temperature_K": ("add", 5.0),  # same variable, PlantInputs name (console injections)
    "cooling_water_temperature_K": ("add", 3.0),
    "steam_pressure_bar": ("mul", 0.10),
    "cstr_heating_utility_temperature_K": ("add", 5.0),
    "ambient_temperature_K": ("add", 3.0),
}


def disturbance_step(target: str, sign: float) -> tuple[str, float, str]:
    """(runtime mode, value, label) for one normal disturbance step on ``target``."""
    mode, size = DISTURBANCE_STEPS[target]
    if mode == "add":
        return "add", sign * size, f"{'+' if sign > 0 else '-'}{size:g} K"
    return "multiply", 1.0 + sign * size, f"{'+' if sign > 0 else '-'}{100 * size:g}%"


def randomized_step_disturbance_scenario(
    duration_min: float = 180.0,
    seed: int = 20261004,
    step_duration_min: float = 15.0,
    magnitude_fraction: float | None = None,
    earliest_start_min: float = 30.0,
    max_disturbances: int = 5,
) -> Scenario:
    """Random subset of 15-min normal disturbances (sizes in ``DISTURBANCE_STEPS``).

    Each selected variable receives one rectangular pulse.  Start times are
    independent, so overlap is allowed.  The seed fully determines the run.
    ``magnitude_fraction`` restores the old behaviour (scale every variable by
    1 +/- fraction) for reproducing earlier datasets.
    """
    duration_h = float(duration_min) / 60.0
    pulse_h = float(step_duration_min) / 60.0
    rng = np.random.default_rng(int(seed))
    candidates = {
        "feed_temperature_K": 298.15,
        "cooling_water_temperature_K": 298.15,
        "steam_pressure_bar": 5.659806566043441,
        "cstr_heating_utility_temperature_K": 390.0,
        "ambient_temperature_K": 298.15,
    }
    nmax = min(max(1, int(max_disturbances)), len(candidates))
    nsel = int(rng.integers(1, nmax + 1))
    names = [str(x) for x in rng.choice(list(candidates), size=nsel, replace=False)]
    kwargs: dict[str, object] = {}
    events: list[ScenarioEvent] = []
    latest_start_h = max(float(earliest_start_min) / 60.0, duration_h - pulse_h)
    lo = min(float(earliest_start_min) / 60.0, max(0.0, duration_h - pulse_h))
    hi = max(lo, duration_h - pulse_h)
    for target in names:
        nominal = candidates[target]
        start = float(rng.uniform(lo, hi)) if hi > lo else lo
        sign = float(rng.choice([-1.0, 1.0]))
        if magnitude_fraction is not None:  # legacy: relative step on every variable
            mult, magnitude, label = 1.0 + sign * float(magnitude_fraction), sign * float(magnitude_fraction), \
                f"{100 * sign * float(magnitude_fraction):+g}%"
        else:
            mode, value, label = disturbance_step(target, sign)
            mult = (nominal + value) / nominal if mode == "add" else value
            magnitude = value if mode == "add" else value - 1.0
        kwargs[target] = _pulse(nominal, start, pulse_h, mult)
        events.append(ScenarioEvent(
            name=f"disturbance_{target}_{'up' if sign > 0 else 'down'}",
            kind="disturbance",
            target=target,
            start_h=start,
            end_h=start + pulse_h,
            magnitude=magnitude,
            metadata=f"{step_duration_min:g} min step {label}",
        ))
    return Scenario(
        duration_h=duration_h,
        name=f"random_step_disturbances_seed_{seed}",
        events=tuple(sorted(events, key=lambda e: e.start_h)),
        **kwargs,
    )


@dataclass(frozen=True)
class ActuatorFault:
    """Fault between safety-arbitrated request and the physical actuator.

    modes:
      capacity      : upper capacity becomes reference * capacity_fraction
      capacity_ramp : upper capacity degrades linearly from 100% to the
                      specified fraction over ramp_duration_h
      freeze        : freeze at requested value when fault becomes active
      fixed         : force a specified fixed value
      stiction      : hold last actual value until request moves outside a deadband
    """
    target: str
    start_h: float
    end_h: float | None = None
    mode: str = "capacity"
    capacity_fraction: float = 1.0
    capacity_reference_value: float | None = None
    ramp_duration_h: float = 0.0
    fixed_value: float | None = None
    stiction_band_fraction: float = 0.05
    name: str = "actuator_fault"

    def active(self, t_h: float) -> bool:
        return t_h >= self.start_h and (self.end_h is None or t_h < self.end_h)


class ActuatorFaultEngine:
    def __init__(self, faults: Sequence[ActuatorFault] | None = None):
        self.faults = list(faults or [])
        self._frozen_values: dict[int, float] = {}
        self._stiction_values: dict[int, float] = {}

    def reset(self) -> None:
        self._frozen_values.clear()
        self._stiction_values.clear()

    def active_faults(self, t_h: float) -> list[ActuatorFault]:
        return [f for f in self.faults if f.active(t_h)]

    def apply(self, t_h: float, requested: PlantInputs, nominal: PlantInputs) -> PlantInputs:
        actual = requested
        for idx, fault in enumerate(self.faults):
            if not fault.active(t_h):
                self._frozen_values.pop(idx, None)
                self._stiction_values.pop(idx, None)
                continue
            if not hasattr(actual, fault.target):
                raise AttributeError(f"Unknown PlantInputs field '{fault.target}'")
            req = float(getattr(actual, fault.target))
            if fault.mode == "capacity":
                ref = (float(getattr(nominal, fault.target)) if fault.capacity_reference_value is None
                       else float(fault.capacity_reference_value))
                cap = ref * fault.capacity_fraction
                value = min(req, cap)
            elif fault.mode == "capacity_ramp":
                ref = (float(getattr(nominal, fault.target)) if fault.capacity_reference_value is None
                       else float(fault.capacity_reference_value))
                if fault.ramp_duration_h <= 0.0:
                    progress = 1.0
                else:
                    progress = min(max((t_h - fault.start_h) / fault.ramp_duration_h, 0.0), 1.0)
                frac = 1.0 + progress * (fault.capacity_fraction - 1.0)
                value = min(req, ref * frac)
            elif fault.mode == "freeze":
                if idx not in self._frozen_values:
                    self._frozen_values[idx] = req
                value = self._frozen_values[idx]
            elif fault.mode == "fixed":
                if fault.fixed_value is None:
                    raise ValueError("fixed actuator fault requires fixed_value")
                value = float(fault.fixed_value)
            elif fault.mode == "stiction":
                if idx not in self._stiction_values:
                    self._stiction_values[idx] = req
                held = self._stiction_values[idx]
                scale = max(abs(float(getattr(nominal, fault.target))), 1.0)
                band = max(0.0, fault.stiction_band_fraction) * scale
                if abs(req - held) > band:
                    held = req
                    self._stiction_values[idx] = held
                value = held
            else:
                raise ValueError(f"Unsupported actuator fault mode '{fault.mode}'")
            actual = replace(actual, **{fault.target: value})
        return actual


@dataclass(frozen=True)
class CampaignBlock:
    block_id: int
    name: str
    scenario: Scenario
    actuator_faults: ActuatorFaultEngine
    reaction_faults: Sequence[ReactionRateFault]
    production_levels: Sequence[float]
    segment_duration_h: float
    global_offset_h: float

    def labels(self, t_h: float) -> dict[str, object]:
        tt = min(max(t_h, 0.0), self.scenario.duration_h - 1e-12)
        segment = min(int(tt // self.segment_duration_h), len(self.production_levels) - 1)
        active_r = [f for f in self.reaction_faults if f.active(t_h)]
        active_a = self.actuator_faults.active_faults(t_h)
        names = [f.name for f in active_r] + [f.name for f in active_a]
        rloss = max((f.loss_fraction(t_h) for f in active_r), default=0.0)
        return {
            "label.block_id": self.block_id,
            "label.block_name": self.name,
            "label.production_segment": segment + 1,
            "label.production_fraction": float(self.production_levels[segment]),
            "label.fault_active": int(bool(names)),
            "label.fault_names": ";".join(names) if names else "none",
            "label.reaction_rate_loss_fraction": float(rloss),
            "label.cstr_heater_frozen": int(any(f.target == "cstr_heater_factor" for f in active_a)),
            "label.bottoms_flow_frozen": int(any(f.target == "bottoms_flow" for f in active_a)),
            "label.reflux_frozen": int(any(f.target == "reflux_flow" and f.mode == "freeze" for f in active_a)),
            "label.reflux_shutdown": int(any(f.target == "reflux_flow" and f.mode == "fixed" and f.fixed_value == 0.0 for f in active_a)),
        }


@dataclass(frozen=True)
class FaultDetectionCampaign:
    """Three independent 600-min experiments that are stacked after simulation."""
    blocks: Sequence[CampaignBlock]
    production_levels: Sequence[float]
    segment_duration_h: float

    @property
    def block_duration_h(self) -> float:
        return len(self.production_levels) * self.segment_duration_h

    @property
    def duration_h(self) -> float:
        return len(self.blocks) * self.block_duration_h

    def event_table(self) -> list[dict[str, object]]:
        rows: list[dict[str, object]] = []
        for block in self.blocks:
            for f in block.reaction_faults:
                rows.append({
                    "fault_name": f.name,
                    "fault_type": "reaction_rate_loss",
                    "target": "catalyst_activity",
                    "block_id": block.block_id,
                    "start_min": round(60.0 * (block.global_offset_h + f.start_h), 9),
                    "end_min": round(60.0 * (block.global_offset_h + f.end_h), 9),
                    "magnitude": f.final_loss_fraction,
                    "mode": "10min_ramp_to_one_third_then_step_to_full_10min_hold",
                })
            for f in block.actuator_faults.faults:
                rows.append({
                    "fault_name": f.name,
                    "fault_type": "actuator",
                    "target": f.target,
                    "block_id": block.block_id,
                    "start_min": round(60.0 * (block.global_offset_h + f.start_h), 9),
                    "end_min": None if f.end_h is None else round(60.0 * (block.global_offset_h + f.end_h), 9),
                    "magnitude": f.capacity_fraction if f.mode == "capacity" else f.fixed_value,
                    "mode": f.mode,
                })
        return sorted(rows, key=lambda r: float(r["start_min"]))

def production_step_trajectory(
    segment_duration_min: float = 120.0,
    levels: Sequence[float] = (1.00, 0.85, 0.70, 0.85, 1.00),
    repeats: int = 1,
) -> tuple[PiecewiseConstant, float]:
    seg_h = float(segment_duration_min) / 60.0
    pts: list[tuple[float, float]] = []
    for b in range(repeats):
        offset = b * len(levels) * seg_h
        for j, level in enumerate(levels):
            pts.append((offset + j * seg_h, float(level)))
    duration_h = repeats * len(levels) * seg_h
    return PiecewiseConstant(pts), duration_h


def base_production_scenario(
    segment_duration_min: float = 120.0,
    levels: Sequence[float] = (1.00, 0.85, 0.70, 0.85, 1.00),
) -> Scenario:
    tr, duration_h = production_step_trajectory(segment_duration_min, levels, repeats=1)
    return Scenario(name="base_production_steps", duration_h=duration_h, throughput_fraction=tr)


def fault_detection_campaign(
    segment_duration_min: float = 120.0,
    production_levels: Sequence[float] = (1.00, 0.85, 0.70, 0.85, 1.00),
) -> FaultDetectionCampaign:
    """Build the requested three-block offline-FDD campaign.

    Each block is simulated independently from the same nominal steady state and
    later stacked with a global time offset. This avoids controller-history leakage
    between experiments and makes the three blocks directly comparable.
    """
    levels = tuple(float(x) for x in production_levels)
    seg_h = float(segment_duration_min) / 60.0
    block_h = len(levels) * seg_h
    min_h = 1.0 / 60.0
    reaction_offset = 20.0 * min_h
    actuator_offset = 5.0 * min_h
    actuator_duration = 20.0 * min_h

    def throughput_scenario(name: str, catalyst: Trajectory = Constant(1.0)) -> Scenario:
        tr, duration_h = production_step_trajectory(segment_duration_min, levels, repeats=1)
        return Scenario(name=name, duration_h=duration_h, throughput_fraction=tr, catalyst_activity=catalyst)

    # Block 1: clean normal operation.
    b1 = CampaignBlock(
        block_id=1,
        name="normal",
        scenario=throughput_scenario("normal"),
        actuator_faults=ActuatorFaultEngine(),
        reaction_faults=(),
        production_levels=levels,
        segment_duration_h=seg_h,
        global_offset_h=0.0,
    )

    # Block 2: one large reaction-rate fault + two frozen control outputs.
    r2 = ReactionRateFault(
        name="reaction_loss_50_block2",
        start_h=1.0 * seg_h + reaction_offset,
        final_loss_fraction=0.50,
    )
    a2 = ActuatorFaultEngine([
        ActuatorFault(
            name="cstr_temperature_valve_freeze",
            target="cstr_heater_factor",
            start_h=2.0 * seg_h + actuator_offset,
            end_h=2.0 * seg_h + actuator_offset + actuator_duration,
            mode="freeze",
        ),
        ActuatorFault(
            name="bottoms_level_valve_freeze",
            target="bottoms_flow",
            start_h=3.0 * seg_h + actuator_offset,
            end_h=3.0 * seg_h + actuator_offset + actuator_duration,
            mode="freeze",
        ),
    ])
    b2 = CampaignBlock(
        block_id=2,
        name="fault_set_1",
        scenario=throughput_scenario("fault_set_1", CatalystActivityTrajectory([r2])),
        actuator_faults=a2,
        reaction_faults=(r2,),
        production_levels=levels,
        segment_duration_h=seg_h,
        global_offset_h=block_h,
    )

    # Block 3: two reaction-rate faults + frozen reflux temperature-control output.
    r31 = ReactionRateFault(
        name="reaction_loss_50_block3",
        start_h=1.0 * seg_h + reaction_offset,
        final_loss_fraction=0.50,
    )
    r32 = ReactionRateFault(
        name="reaction_loss_30_block3",
        start_h=2.0 * seg_h + reaction_offset,
        final_loss_fraction=0.30,
    )
    a3 = ActuatorFaultEngine([
        ActuatorFault(
            name="reflux_temperature_control_freeze",
            target="reflux_flow",
            start_h=3.0 * seg_h + actuator_offset,
            end_h=3.0 * seg_h + actuator_offset + actuator_duration,
            mode="freeze",
        ),
    ])
    b3 = CampaignBlock(
        block_id=3,
        name="fault_set_2",
        scenario=throughput_scenario("fault_set_2", CatalystActivityTrajectory([r31, r32])),
        actuator_faults=a3,
        reaction_faults=(r31, r32),
        production_levels=levels,
        segment_duration_h=seg_h,
        global_offset_h=2.0 * block_h,
    )

    return FaultDetectionCampaign(
        blocks=(b1, b2, b3),
        production_levels=levels,
        segment_duration_h=seg_h,
    )

fdd/diagnosis.py:
"""Rule checks and contribution-based fault diagnosis.

Everything here uses operator observations only (no simulator ground truth),
so it is safe to run inside an autonomous monitoring agent.
"""
from __future__ import annotations

from typing import Mapping

from integrated_plant.alarms import default_alarm_definitions

from .pca import PCAScore

ALARM_TAGS = {d.alarm_id: d.tag for d in default_alarm_definitions()}

ACTIVE_ALARM_STATES = ("ACTIVE_UNACK", "ACTIVE_ACK")

# Which plant section / fault classes a feature points to when it dominates the
# PCA contributions. Fault class names match the simulator's fault library so
# diagnosis accuracy can be scored against episode ground truth offline.
VARIABLE_KNOWLEDGE: dict[str, tuple[str, tuple[str, ...]]] = {
    "meas.cstr_pressure_bar": ("R-101 pressure / H2 vent", ("h2_pcv_capacity_degradation", "h2_pcv_stuck_closed", "reactor_pressure_sensor_low_bias")),
    "op.R_PIC": ("R-101 pressure / H2 vent", ("h2_pcv_capacity_degradation", "h2_pcv_stuck_closed")),
    "meas.cstr_h2_vent_kmol_h": ("R-101 pressure / H2 vent", ("h2_pcv_stuck_closed", "catalyst_activity_loss")),
    "meas.cstr_temperature_K": ("R-101 heating", ("reactor_heater_stuck_high", "catalyst_activity_loss")),
    "op.R_TIC": ("R-101 heating", ("reactor_heater_stuck_high",)),
    "meas.cstr_x_acetone": ("R-101 conversion", ("catalyst_activity_loss",)),
    "meas.cstr_holdup_kmol": ("R-101 inventory", ("cstr_outlet_capacity_loss", "cstr_liquid_leak")),
    "op.R_LIC": ("R-101 inventory", ("cstr_outlet_capacity_loss", "cstr_liquid_leak")),
    "meas.column_pressure_bar": ("C-201 pressure / condenser", ("condenser_cooling_loss",)),
    "op.COL_PIC": ("C-201 pressure / condenser", ("condenser_cooling_loss",)),
    "meas.top_pressure_bar": ("C-201 pressure / condenser", ("condenser_cooling_loss",)),
    "meas.drum_holdup_kmol": ("Reflux drum inventory", ("reflux_drum_leak", "reflux_pump_trip")),
    "op.DR_LIC": ("Reflux drum inventory", ("reflux_drum_leak",)),
    "meas.top_temperature_K": ("C-201 top / reflux", ("reflux_pump_trip", "reflux_valve_stiction", "top_temperature_sensor_freeze")),
    "op.TOP_TIC": ("C-201 top / reflux", ("reflux_pump_trip", "reflux_valve_stiction")),
    "meas.distillate_x_acetone": ("C-201 separation", ("reflux_pump_trip", "condenser_cooling_loss")),
    "meas.reboiler_holdup_kmol": ("Reboiler inventory", ("reboiler_liquid_leak",)),
    "op.RB_LIC": ("Reboiler inventory", ("reboiler_liquid_leak",)),
    "meas.bottom_temperature_K": ("Reboiler heating", ()),
    "op.BOT_TIC": ("Reboiler heating", ()),
    "meas.bottoms_x_acetone": ("C-201 separation", ()),
}


def _section_for(variable: str) -> tuple[str, tuple[str, ...]]:
    if variable in VARIABLE_KNOWLEDGE:
        return VARIABLE_KNOWLEDGE[variable]
    if variable.startswith("meas.tray_"):
        return ("C-201 tray profile", ("reflux_pump_trip", "condenser_cooling_loss"))
    return ("unmapped", ())


def rule_checks(observation: Mapping) -> dict:
    """Deterministic indications from alarms, pumps, SIFs and controller margins."""
    failed = [t for t, info in observation["pump_trains"].items() if info["selected_failed"]]
    alarms = [a for a, s in observation["alarm_states"].items() if s in ACTIVE_ALARM_STATES]
    saturated = []
    for loop, info in observation["controllers"].items():
        lo, hi, out = info["mv_min"], info["mv_max"], info["last_output"]
        if hi > lo and info["mode"] == "AUTO":
            frac = (out - lo) / (hi - lo)
            span = info["sp_max"] - info["sp_min"]
            if (frac >= 0.97 or frac <= 0.03) and abs(info["pv"] - info["setpoint"]) > 0.03 * span:
                saturated.append(loop)
    sif = list(observation.get("sif_latched", ()))
    return {"failed_trains": failed, "active_alarms": alarms,
            "saturated_loops": saturated, "sif_latched": sif,
            "plant_trip": bool(observation.get("plant_trip_latched")),
            "abnormal": bool(failed or alarms or saturated or sif)}


def diagnose(score: PCAScore | None, rules: Mapping, n_contrib: int = 6) -> dict:
    """Rank fault hypotheses from rule evidence and PCA contributions."""
    hypotheses: dict[str, dict] = {}

    failed = {t.lower() for t in rules["failed_trains"]}

    def add(name: str, weight: float, evidence: str):
        # Pump status is directly observable: never hypothesise a trip of a pump that is running.
        if name.endswith("_pump_trip") and name.removesuffix("_pump_trip") not in failed:
            return
        h = hypotheses.setdefault(name, {"fault": name, "score": 0.0, "evidence": []})
        h["score"] += weight
        h["evidence"].append(evidence)

    for train in rules["failed_trains"]:
        add(f"{train.lower()}_pump_trip", 10.0, f"selected {train} pump reports failed")
    for loop in rules["saturated_loops"]:
        add(f"{loop}_out_of_range", 2.0, f"{loop} output saturated with PV off setpoint")
    # Alarms point at fault modes through the variable they monitor (useful before PCA confirms).
    for alarm in rules["active_alarms"]:
        tag = ALARM_TAGS.get(alarm, "")
        if tag.startswith("pump_"):
            continue  # pump trips are already covered by failed_trains
        for f in _section_for(f"meas.{tag}")[1]:
            add(f, 1.0, f"alarm {alarm} on {tag}")

    sections: dict[str, float] = {}
    contributors = score.top_contributors(n_contrib) if score is not None else []
    if score is not None and score.violation:
        total = sum(c["score"] for c in contributors) or 1.0
        for c in contributors:
            section, faults = _section_for(c["variable"])
            share = c["score"] / total
            sections[section] = sections.get(section, 0.0) + share
            for f in faults:
                add(f, 3.0 * share, f"{c['variable']} contributes {100*share:.0f}%")
        # One variable explaining most of a residual violation, with its own
        # loop not compensating, is the classic signature of a sensor fault.
        if score.spe_violation and contributors:
            spe_total = sum(score.spe_contrib.values()) or 1.0
            top = max(score.spe_contrib.items(), key=lambda kv: kv[1])
            if top[1] / spe_total > 0.6:
                add(f"sensor_fault:{top[0]}", 2.5, f"{top[0]} explains {100*top[1]/spe_total:.0f}% of SPE")

    ranked = sorted(hypotheses.values(), key=lambda h: -h["score"])
    return {"hypotheses": ranked[:5],
            "sections": sorted(({"section": k, "share": v} for k, v in sections.items()),
                               key=lambda s: -s["share"]),
            "contributors": contributors,
            "summary": ranked[0]["fault"] if ranked else "no fault isolated"}

fdd/pca.py:
"""PCA process monitoring: Hotelling T², SPE (Q) and contribution analysis.

The model is trained on normal operating data only. At run time each operator
observation is mapped to a feature vector (BPCS measurements plus controller
outputs), scaled with the training statistics and projected on the retained
principal components.

    T²  = t Λ⁻¹ tᵀ            variation *inside* the PCA model (abnormal
                                 magnitudes of normal correlations)
    SPE = ‖x − x P Pᵀ‖²       variation *outside* the model (broken
                                 correlations, e.g. sensor faults)

Limits use the F distribution for T² and Box's χ² approximation for SPE.
Contributions (complete decomposition) rank the variables driving an alarm and
are the input to the diagnosis step.
"""
from __future__ import annotations

from dataclasses import dataclass, field
import json
import math
from pathlib import Path
from typing import Iterable, Mapping

import numpy as np
from scipy import stats

# Pump failure flags are binary indications and are handled by rule checks.
EXCLUDED_MEASUREMENT_PREFIXES = ("pump_",)


def observation_features(observation: Mapping) -> dict[str, float]:
    """Feature dictionary from an ``EpisodeRunner.observation()``."""
    feats = {
        f"meas.{k}": float(v) for k, v in observation["measurements"].items()
        if not k.startswith(EXCLUDED_MEASUREMENT_PREFIXES)
    }
    for loop_id, info in observation["controllers"].items():
        feats[f"op.{loop_id}"] = float(info["last_output"])
    return feats


def record_features(record: Mapping) -> dict[str, float]:
    """Same features from an ``EpisodeRunner.records`` row (or its CSV)."""
    feats: dict[str, float] = {}
    for key, value in record.items():
        if key.startswith("meas.") and not key[5:].startswith(EXCLUDED_MEASUREMENT_PREFIXES):
            feats[key] = float(value)
        elif key.startswith("loop.") and key.endswith(".op"):
            feats[f"op.{key.split('.')[1]}"] = float(value)
    return feats


@dataclass
class PCAScore:
    t2: float
    spe: float
    t2_limit: float
    spe_limit: float
    t2_contrib: dict[str, float] = field(default_factory=dict)
    spe_contrib: dict[str, float] = field(default_factory=dict)

    @property
    def t2_violation(self) -> bool:
        return self.t2 > self.t2_limit

    @property
    def spe_violation(self) -> bool:
        return self.spe > self.spe_limit

    @property
    def violation(self) -> bool:
        return self.t2_violation or self.spe_violation

    def top_contributors(self, n: int = 5) -> list[dict[str, float]]:
        """Variables ranked by normalised combined contribution."""
        t2n = {k: max(v, 0.0) / self.t2_limit for k, v in self.t2_contrib.items()}
        spen = {k: v / self.spe_limit for k, v in self.spe_contrib.items()}
        combined = {k: t2n.get(k, 0.0) + spen.get(k, 0.0) for k in set(t2n) | set(spen)}
        ranked = sorted(combined.items(), key=lambda kv: -kv[1])[:n]
        return [{"variable": k, "score": float(v),
                 "t2": float(self.t2_contrib.get(k, 0.0)),
                 "spe": float(self.spe_contrib.get(k, 0.0))} for k, v in ranked]

    def to_dict(self, n_contrib: int = 8) -> dict:
        return {"t2": self.t2, "spe": self.spe, "t2_limit": self.t2_limit,
                "spe_limit": self.spe_limit, "t2_violation": self.t2_violation,
                "spe_violation": self.spe_violation,
                "top_contributors": self.top_contributors(n_contrib)}


class PCAMonitor:
    """Static PCA monitor with T²/SPE limits and contribution analysis."""

    def __init__(self, variables: list[str], mean: np.ndarray, std: np.ndarray,
                 loadings: np.ndarray, eigenvalues: np.ndarray,
                 t2_limit: float, spe_limit: float, meta: dict | None = None):
        self.variables = list(variables)
        self.mean = np.asarray(mean, dtype=float)
        self.std = np.asarray(std, dtype=float)
        self.P = np.asarray(loadings, dtype=float)          # (m, k)
        self.lam = np.asarray(eigenvalues, dtype=float)     # (k,)
        self.t2_limit = float(t2_limit)
        self.spe_limit = float(spe_limit)
        self.meta = dict(meta or {})

    # ------------------------------------------------------------------ fit
    @classmethod
    def fit(cls, X: np.ndarray, variables: list[str], *, cpv: float = 0.90,
            n_components: int | None = None, alpha: float = 0.99,
            limits: str = "max", min_std: float = 1e-9) -> "PCAMonitor":
        X = np.asarray(X, dtype=float)
        if X.ndim != 2 or X.shape[1] != len(variables):
            raise ValueError("X must be (n_samples, n_variables)")
        keep = np.all(np.isfinite(X), axis=1)
        X = X[keep]
        n, m = X.shape
        if n <= m:
            raise ValueError(f"Need more samples ({n}) than variables ({m})")

        mean = X.mean(axis=0)
        std = X.std(axis=0, ddof=1)
        # Constant variables carry no information; keep them but never scale up noise.
        std = np.where(std < min_std, 1.0, std)
        Z = (X - mean) / std

        _, s, Vt = np.linalg.svd(Z, full_matrices=False)
        eig = s**2 / (n - 1)
        if n_components is None:
            frac = np.cumsum(eig) / eig.sum()
            n_components = int(np.searchsorted(frac, cpv) + 1)
        k = int(min(max(n_components, 1), m - 1))
        P = Vt[:k].T
        lam = eig[:k]

        T = Z @ P
        t2 = np.sum(T**2 / lam, axis=1)
        t2_theory = k * (n - 1) * (n + 1) / (n * (n - k)) * stats.f.ppf(alpha, k, n - k)

        # Box (1954): SPE ~ g·χ²_h, moments matched on the training SPE.
        R = Z - T @ P.T
        spe = np.sum(R**2, axis=1)
        mu, var = spe.mean(), spe.var(ddof=1)
        g, h = var / (2 * mu), 2 * mu**2 / var
        spe_theory = g * stats.chi2.ppf(alpha, h)

        # Closed-loop plant data are autocorrelated and non-Gaussian (setpoint
        # and disturbance steps), so the theoretical limits are optimistic.
        # "max" (default) never goes below the empirical alpha-quantile of the
        # training data; "theory" is more sensitive but alarms more often.
        t2_emp, spe_emp = float(np.quantile(t2, alpha)), float(np.quantile(spe, alpha))
        if limits == "theory":
            t2_lim, spe_lim = t2_theory, spe_theory
        elif limits == "empirical":
            t2_lim, spe_lim = t2_emp, spe_emp
        elif limits == "max":
            t2_lim, spe_lim = max(t2_theory, t2_emp), max(spe_theory, spe_emp)
        else:
            raise ValueError("limits must be 'theory', 'empirical' or 'max'")

        meta = {"n_samples": int(n), "n_components": k, "alpha": alpha,
                "explained_variance": float(eig[:k].sum() / eig.sum()),
                "limits": limits, "t2_limit_theory": float(t2_theory), "spe_limit_theory": float(spe_theory)}
        return cls(variables, mean, std, P, lam, t2_lim, spe_lim, meta)

    # ---------------------------------------------------------------- score
    def vector(self, features: Mapping[str, float]) -> np.ndarray:
        missing = [v for v in self.variables if v not in features]
        if missing:
            raise KeyError(f"Missing PCA features: {missing[:5]}")
        return np.array([features[v] for v in self.variables], dtype=float)

    def score_vector(self, x: np.ndarray) -> PCAScore:
        z = (np.asarray(x, dtype=float) - self.mean) / self.std
        t = z @ self.P
        t2 = float(np.sum(t**2 / self.lam))
        r = z - t @ self.P.T
        spe = float(r @ r)
        # Complete decomposition: c_i = z_i * (P Λ⁻¹ Pᵀ z)_i, sums to T².
        t2c = z * (self.P @ (t / self.lam))
        return PCAScore(t2, spe, self.t2_limit, self.spe_limit,
                        dict(zip(self.variables, map(float, t2c))),
                        dict(zip(self.variables, map(float, r**2))))

    def score(self, features: Mapping[str, float]) -> PCAScore:
        return self.score_vector(self.vector(features))

    def score_observation(self, observation: Mapping) -> PCAScore:
        return self.score(observation_features(observation))

    # ------------------------------------------------------------ persist
    def to_dict(self) -> dict:
        return {"variables": self.variables, "mean": self.mean.tolist(),
                "std": self.std.tolist(), "loadings": self.P.tolist(),
                "eigenvalues": self.lam.tolist(), "t2_limit": self.t2_limit,
                "spe_limit": self.spe_limit, "meta": self.meta}

    def save(self, path: str | Path) -> None:
        Path(path).parent.mkdir(parents=True, exist_ok=True)
        Path(path).write_text(json.dumps(self.to_dict(), indent=1), encoding="utf-8")

    @classmethod
    def load(cls, path: str | Path) -> "PCAMonitor":
        d = json.loads(Path(path).read_text(encoding="utf-8"))
        return cls(d["variables"], d["mean"], d["std"], d["loadings"],
                   d["eigenvalues"], d["t2_limit"], d["spe_limit"], d.get("meta"))


def matrix_from_feature_rows(rows: Iterable[Mapping[str, float]]) -> tuple[np.ndarray, list[str]]:
    rows = list(rows)
    variables = sorted(set.intersection(*(set(r) for r in rows)))
    X = np.array([[r[v] for v in variables] for r in rows], dtype=float)
    return X, variables


def finite_or_none(x: float) -> float | None:
    return float(x) if math.isfinite(x) else None

server/plant_service.py:
"""Asyncio service that owns the live ``EpisodeRunner``.

It is the single place where the simulator is mutated, so the UI (WebSocket or the
browser worker), the FDD monitor and scripts all go through it:

* the run loop steps the plant on a worker thread (the DAE solve is CPU bound) so the
  event loop stays free for UI messages; with ``threaded=False`` (browser / Pyodide)
  it steps inline;
* an ``asyncio.Lock`` serialises plant steps, operator actions and fault injections;
* every tick is broadcast to subscribers and the latest observation is offered to the
  FDD monitor with "latest wins" semantics;
* a fault campaign (server/campaigns.py) can fire timed injections in sim time
  and writes a per-fault report to campaign_results/ when it finishes.

No FastAPI imports here: ``fault_campaign.py`` and the browser build use it without a server.
"""
from __future__ import annotations

import asyncio
from collections import deque
from dataclasses import asdict, is_dataclass, replace
from datetime import datetime
from enum import Enum
import json
import math
from pathlib import Path
import time
from typing import Any, Awaitable, Callable

from integrated_plant import (
    ActuatorFault, CURATED_EPISODES, EpisodeRunner, EpisodeTiming, IntegratedPlantDAE,
    PUMP_IDS, PUMP_TRAINS, PumpFault, RuntimeInputEvent, SensorFault, SupervisoryAction,
    curated_episode, nominal_episode, normal_variability_episode, surprise_episode,
)
from integrated_plant.scenario import disturbance_step

SCENARIOS = ["nominal", "variability", "surprise", *CURATED_EPISODES]
DISTURBANCES = {
    "fresh_feed_temperature_K": "Feed temperature",
    "cooling_water_temperature_K": "Cooling-water temperature",
    "steam_pressure_bar": "Steam-header pressure",
    "cstr_heating_utility_temperature_K": "CSTR heating-utility temperature",
    "ambient_temperature_K": "Ambient temperature",
}
ACTUATOR_TARGETS = ["fresh_ipa_feed", "cstr_outflow", "cstr_heater_factor", "cstr_vent_valve",
                    "cstr_bdv_valve", "reflux_flow", "steam_factor", "bottoms_flow",
                    "distillate_flow", "condenser_cooling_valve"]
SENSOR_TARGETS = ["cstr_pressure_bar", "cstr_temperature_K", "cstr_holdup_kmol", "column_pressure_bar",
                  "top_temperature_K", "bottom_temperature_K", "reboiler_holdup_kmol", "drum_holdup_kmol"]
PROCESS_FAULTS = ["catalyst_activity_loss", "cstr_liquid_leak", "reboiler_liquid_leak",
                  "drum_liquid_leak", "condenser_cooling_loss"]


def jsonable(obj: Any) -> Any:
    """JSON-safe copy: NaN/inf -> None, tuples -> lists, enums/dataclasses unpacked."""
    if isinstance(obj, float):
        return obj if math.isfinite(obj) else None
    if isinstance(obj, (str, int, bool)) or obj is None:
        return obj
    if isinstance(obj, Enum):
        return obj.value
    if is_dataclass(obj) and not isinstance(obj, type):
        return jsonable(asdict(obj))
    if isinstance(obj, dict):
        return {str(k): jsonable(v) for k, v in obj.items()}
    if isinstance(obj, (list, tuple, set, deque)):
        return [jsonable(v) for v in obj]
    if hasattr(obj, "item"):  # numpy scalar
        return jsonable(obj.item())
    return str(obj)


# Bump when the WebSocket messages change; the console warns if the backend is older.
API_VERSION = 7


class PlantService:
    TIMING = EpisodeTiming(plant_step_min=0.1, decision_interval_min=0.5, control_interval_min=1.0)

    def __init__(self, history_len: int = 1440, threaded: bool = True):
        # threaded=False runs the DAE solve on the event loop itself (browser / Pyodide has no threads).
        self.threaded = threaded
        self.plant = IntegratedPlantDAE()
        self.env: EpisodeRunner | None = None
        self.lock = asyncio.Lock()
        self.running = False
        self.tick_delay_s = 0.0
        # Pacing: sleep pace_sleep_s after every pace_every plant iterations (0.5 sim-min each).
        self.pace_every, self.pace_sleep_s, self._iterations = 10, 0.05, 0
        # Hold the plant while the agents are mid-decision (KG → plan → act → twin → reprompt),
        # so their action lands on the state they analysed. Released by the supervisor or a timeout.
        self.hold_for_agents = False  # plant-only build: nothing holds the plant
        # LLM calls + several 30-min twin rollouts can take minutes; release the plant only
        # after this long (and say so), so a stuck decision never freezes it forever.
        self.hold_timeout_s = 600.0
        self._hold_timeout_reported = False
        self._agent_hold_since: float | None = None
        self.config = {"scenario": "nominal", "horizon_min": 360.0, "seed": 20261004, "stop_on_trip": False}
        self.trend: deque = deque(maxlen=history_len)
        self.history: deque = deque(maxlen=history_len)   # measurements + loop OP/SP (chat agent trends)
        self.monitor: deque = deque(maxlen=history_len)
        self.campaign: dict | None = None
        self.campaign_dir = Path(__file__).resolve().parent.parent / "campaign_results"
        self.agent_log: deque = deque(maxlen=600)
        self.messages: deque = deque(maxlen=50)
        self._subscribers: set[asyncio.Queue] = set()
        self._obs_queue: asyncio.Queue = asyncio.Queue(maxsize=1)
        self._wake = asyncio.Event()
        self._pending_reset_sif = False
        self._task: asyncio.Task | None = None
        # Extension points used by the agent supervisor.
        self.command_handlers: dict[str, Callable[[dict], Awaitable[dict]]] = {}
        self.on_load: list[Callable[[], Awaitable[None]]] = []
        self.hello_extras: list[Callable[[], dict]] = []

    async def _call(self, fn, *args, **kwargs):
        """Run a CPU-bound call on a worker thread (server) or inline (browser)."""
        if self.threaded:
            return await asyncio.to_thread(fn, *args, **kwargs)
        return fn(*args, **kwargs)

    # ------------------------------------------------------------ lifecycle
    async def start(self) -> None:
        if self.env is None:
            await self.load(self.config)
        self._task = asyncio.create_task(self._run_loop(), name="plant-loop")

    async def stop(self) -> None:
        if self._task:
            self._task.cancel()
            try:
                await self._task
            except asyncio.CancelledError:
                pass

    def _build_spec(self, cfg: dict):
        mode, horizon, seed = cfg["scenario"], float(cfg["horizon_min"]), int(cfg["seed"])
        if mode == "nominal":
            spec = nominal_episode(horizon)
        elif mode == "variability":
            spec = normal_variability_episode(horizon, seed)
        elif mode == "surprise":
            spec = surprise_episode(horizon, seed)
        elif mode in CURATED_EPISODES:
            spec = curated_episode(mode, horizon)
        else:
            raise ValueError(f"unknown scenario {mode!r}")
        return replace(spec, terminate_on_plant_trip=bool(cfg["stop_on_trip"]),
                       allow_recovery_termination=False)

    async def load(self, cfg: dict) -> None:
        cfg = {**self.config, **{k: v for k, v in cfg.items() if k in self.config}}
        spec = self._build_spec(cfg)
        async with self.lock:
            self.running = False
            self.config = cfg
            self.env = await self._call(EpisodeRunner, self.plant, spec, timing=self.TIMING)
            self.trend.clear()
            self.history.clear()
            self.monitor.clear()
            self.agent_log.clear()
            self._pending_reset_sif = False
            self.campaign = None  # a new episode cancels a running campaign
            snap = self.snapshot()
            self.trend.append(snap["trend"])
            self.history.append(self._history_row(snap))
        for hook in self.on_load:
            await hook()
        await self.broadcast({"type": "reset", "hello": self.hello()})
        self._offer_observation()
        await self.notify(f"Loaded episode {spec.name}")

    # ------------------------------------------------------------ pub/sub
    def subscribe(self, maxsize: int = 256) -> asyncio.Queue:
        q: asyncio.Queue = asyncio.Queue(maxsize=maxsize)
        self._subscribers.add(q)
        return q

    def unsubscribe(self, q: asyncio.Queue) -> None:
        self._subscribers.discard(q)

    async def broadcast(self, event: dict) -> None:
        event = jsonable(event)
        if event.get("type") == "monitor":
            self.monitor.append(event)
        elif event.get("type") == "agent":
            self.agent_log.append(event)
        for q in list(self._subscribers):
            if q.full():  # slow client: drop its oldest message rather than block the plant
                try:
                    q.get_nowait()
                except asyncio.QueueEmpty:
                    pass
            q.put_nowait(event)

    async def notify(self, text: str, level: str = "info") -> None:
        msg = {"type": "message", "level": level, "text": text,
               "time_min": 60.0 * self.env.t_h if self.env else 0.0}
        self.messages.append(msg)
        await self.broadcast(msg)

    def _offer_observation(self) -> None:
        """Latest-wins hand-off to the agents: a stale observation is replaced."""
        if self.env is None:
            return
        item = (self.env.observation(), self.env.action_catalog())
        if self._obs_queue.full():
            self._obs_queue.get_nowait()
        self._obs_queue.put_nowait(item)

    async def next_observation(self) -> tuple[dict, dict]:
        return await self._obs_queue.get()

    # ------------------------------------------------------------ stepping
    async def _tick(self) -> None:
        async with self.lock:
            env = self.env
            if env is None or env.done:
                self.running = False
                return
            action = SupervisoryAction(reset_sifs=self._pending_reset_sif,
                                       note="console_sif_reset" if self._pending_reset_sif else "")
            self._pending_reset_sif = False
            await self._call(env.step, action)
            snap = self.snapshot()
            self.trend.append(snap["trend"])
            self.history.append(self._history_row(snap))
            if env.done:
                self.running = False
        await self.broadcast({"type": "snapshot", **snap})
        self._offer_observation()
        if env.done:
            await self.notify(f"Episode ended: {env.outcomes.state.status.value} ({env.outcomes.state.reason})", "warn")
        await self._campaign_due()

    @staticmethod
    def _history_row(snap: dict) -> dict:
        row = {"t": snap["time_min"], **snap["measurements"]}
        for loop, c in snap["controllers"].items():
            row[f"op.{loop}"], row[f"sp.{loop}"] = c["last_output"], c["setpoint"]
        for k in ("feed", "outflow", "reflux", "distillate", "bottoms", "heater", "steam", "cooling", "pcv", "bdv", "h2"):
            row[k] = snap["trend"][k]
        return row

    async def _run_loop(self) -> None:
        loop = asyncio.get_running_loop()
        while True:
            if not self.running:
                self._wake.clear()
                await self._wake.wait()
                continue
            if self.held:
                await asyncio.sleep(0.1)
                continue
            if self._agent_hold_since is not None and self.hold_for_agents and not self._hold_timeout_reported:
                self._hold_timeout_reported = True
                await self.notify(f"Agents still deciding after {self.hold_timeout_s:.0f} s: plant released; "
                                  "it runs on while the decision finishes", "warn")
            t0 = loop.time()
            await self._tick()
            self._iterations += 1
            pace = self.pace_sleep_s if self.pace_every > 0 and self._iterations % self.pace_every == 0 else 0.0
            await asyncio.sleep(max(0.0, self.tick_delay_s - (loop.time() - t0)) + pace)

    @property
    def held(self) -> bool:
        if not self.hold_for_agents or self._agent_hold_since is None:
            return False
        if time.monotonic() - self._agent_hold_since > self.hold_timeout_s:
            return False  # never let a stuck decision freeze the plant forever
        return True

    async def set_agent_hold(self, on: bool) -> None:
        was = self.held
        self._agent_hold_since = time.monotonic() if on else None
        self._hold_timeout_reported = False
        if self.held != was:
            await self.broadcast({"type": "status", **self.status()})

    def set_running(self, running: bool) -> None:
        self.running = bool(running) and self.env is not None and not self.env.done
        if self.running:
            self._wake.set()

    async def step(self, minutes: float) -> None:
        self.running = False
        n = max(1, int(round(minutes / self.TIMING.decision_interval_min)))
        for _ in range(n):
            if self.env is None or self.env.done:
                break
            await self._tick()

    # ------------------------------------------------------------ actions
    async def apply_action(self, action: SupervisoryAction, source: str = "operator") -> dict:
        async with self.lock:
            if self.env is None:
                return {"ok": False, "summary": "no episode loaded"}
            result = self.env.apply_action(action)
            snap = self.snapshot()
        await self.broadcast({"type": "snapshot", **snap})
        await self.notify(f"[{source}] {result.summary}", "info" if result.ok else "error")
        return {"ok": result.ok, "summary": result.summary,
                "accepted": list(result.accepted), "rejected": list(result.rejected)}

    async def handle_command(self, msg: dict) -> dict:
        """Dispatch a UI/remote command. Returns an ack dict."""
        kind = msg.get("type")
        try:
            if kind == "load":
                await self.load(msg)
            elif kind == "run":
                if self.env is None or self.env.done:
                    await self.load(self.config)
                self.set_running(True)
            elif kind == "pause":
                self.set_running(False)
            elif kind == "step":
                await self.step(float(msg.get("minutes", 1.0)))
            elif kind == "speed":
                self.tick_delay_s = max(0.0, float(msg.get("delay_ms", 0)) / 1000.0)
            elif kind == "pace":
                self.pace_every = max(0, int(msg.get("every", self.pace_every)))
                self.pace_sleep_s = max(0.0, float(msg.get("sleep_s", self.pace_sleep_s)))
            elif kind == "hold_for_agents":
                self.hold_for_agents = bool(msg.get("on", True))
            elif kind == "ack_all":
                return await self.apply_action(SupervisoryAction(acknowledge_all_alarms=True))
            elif kind == "reset_sif":
                self._pending_reset_sif = True
                await self.notify("SIF reset requested; applied on next plant tick")
            elif kind == "action":
                return await self.apply_action(self._parse_action(msg.get("action", {})))
            elif kind == "inject":
                return await self._inject(msg)
            elif kind == "clear_injections":
                await self._clear_injections()
            elif kind == "campaign_start":
                return await self.start_campaign(msg)
            elif kind == "campaign_stop":
                return await self.stop_campaign("stopped by operator")
            elif kind in self.command_handlers:
                return await self.command_handlers[kind](msg)
            else:
                return {"ok": False, "summary": f"unknown command {kind!r}"}
        except Exception as exc:
            await self.notify(f"{kind}: {exc}", "error")
            return {"ok": False, "summary": str(exc)}
        await self.broadcast({"type": "status", **self.status()})
        return {"ok": True, "summary": kind}

    @staticmethod
    def _parse_action(d: dict) -> SupervisoryAction:
        allowed = {"throughput_target", "setpoints", "modes", "manual_outputs", "auxiliary_commands",
                   "start_spares", "select_primaries", "acknowledge_alarm_ids", "note"}
        bad = set(d) - allowed
        if bad:
            raise ValueError(f"fields not available to operators: {sorted(bad)}")
        kw = dict(d)
        for k in ("start_spares", "select_primaries", "acknowledge_alarm_ids"):
            if k in kw:
                kw[k] = tuple(kw[k])
        return SupervisoryAction(**kw)

    # ------------------------------------------------------------ master injections
    async def _inject(self, m: dict) -> dict:
        async with self.lock:
            env = self.env
            if env is None or env.done:
                raise RuntimeError("load a live episode before injecting")
            t = env.t_h
            end = None if float(m.get("duration_min", 0)) <= 0 else t + float(m["duration_min"]) / 60.0
            kind, stamp = m["kind"], f"{60 * t:.1f}min"
            if kind == "disturbance":
                target = m["target"]
                if target not in DISTURBANCES:
                    raise ValueError(target)
                if "multiplier" in m:  # explicit custom scaling (legacy)
                    mode, value, label = "multiply", float(m["multiplier"]), f"×{float(m['multiplier']):g}"
                else:  # standard normal-disturbance step (+3 K cooling water, +10 % steam pressure, ...)
                    mode, value, label = disturbance_step(target, 1.0 if float(m.get("direction", 1)) >= 0 else -1.0)
                env.runtime_inputs.add(RuntimeInputEvent(
                    f"manual_{target}_{label}_{stamp}", "disturbance", target, t,
                    end if end is not None else t + 0.25, mode, value))
                text = f"{DISTURBANCES[target]} {label}"
            elif kind == "actuator":
                # The console sends severity_pct; campaigns may give absolute values instead.
                target, mode, frac = m["target"], m.get("mode", "freeze"), float(m.get("severity_pct", 50)) / 100
                kw: dict = dict(name=f"manual_{target}_{mode}_{stamp}", target=target, start_h=t, end_h=end, mode=mode)
                if mode in ("capacity", "capacity_ramp"):
                    kw["capacity_fraction"] = float(m.get("capacity_fraction", frac))
                    if mode == "capacity_ramp":
                        kw["capacity_reference_value"] = 1.0 if target.endswith("_valve") else None
                        kw["ramp_duration_h"] = float(m.get("ramp_min", 10.0)) / 60.0
                elif mode == "fixed":
                    kw["fixed_value"] = (float(m["fixed_value"]) if "fixed_value" in m
                                         else float(getattr(env.nominal, target)) * frac)
                elif mode == "stiction":
                    kw["stiction_band_fraction"] = float(m.get("stiction_band_fraction", frac))
                env.spec.actuator_faults.faults.append(ActuatorFault(**kw))
                text = f"actuator {target} {mode}"
            elif kind == "pump":
                pid = m["pump_id"]
                if pid not in PUMP_IDS:
                    raise ValueError(pid)
                env.spec.pump_faults.faults.append(PumpFault(pid, t, end, f"manual_{pid}_trip_{stamp}"))
                text = f"pump {pid} trip"
            elif kind == "sensor":
                target, mode = m["target"], m.get("mode", "bias")
                bias = (float(m["bias"]) if "bias" in m
                        else float(self.plant.measurements(env.y)[target]) * float(m.get("bias_pct", -20)) / 100)
                env.spec.sensor_faults.faults.append(SensorFault(
                    target, t, end, mode, bias if mode == "bias" else 0.0, f"manual_{target}_{mode}_{stamp}"))
                text = f"sensor {target} {mode}"
            elif kind == "process":
                ftype, sev = m["fault"], float(m.get("severity", 50))
                if ftype == "catalyst_activity_loss":
                    target, value = "catalyst_activity", max(0.0, 1 - sev / 100)
                elif ftype == "condenser_cooling_loss":
                    target, value = "condenser_cooling_effectiveness", max(0.0, 1 - sev / 100)
                else:
                    target, value = f"{ftype.removesuffix('_leak')}_leak_kmol_h", max(0.0, sev)
                env.runtime_inputs.add(RuntimeInputEvent(f"manual_{ftype}_{stamp}", "process_fault",
                                                         target, t, end, "set", value))
                text = f"process fault {ftype}"
            else:
                raise ValueError(f"unknown injection kind {kind!r}")
        await self.notify(f"[master] injected {text}", "warn")
        await self.broadcast({"type": "status", **self.status()})
        return {"ok": True, "summary": f"injected {text}"}

    async def _clear_injections(self) -> None:
        async with self.lock:
            env = self.env
            t = env.t_h
            env.clear_runtime_injections()
            for eng in (env.spec.actuator_faults, env.spec.sensor_faults, env.spec.pump_faults):
                eng.faults = [replace(f, end_h=t) if f.active(t) and f.name.startswith("manual_") else f
                              for f in eng.faults]
        await self.notify("[master] all active manual injections ended", "warn")

    # ------------------------------------------------------------ fault campaigns
    async def start_campaign(self, msg: dict) -> dict:
        from .campaigns import build_campaign
        random_kw = {k: msg[k] for k in ("seed", "n", "gap_min", "duration_min") if k in msg}
        name, items = build_campaign(msg.get("campaign", "demo"), **random_kw)
        tail = float(msg.get("tail_min", 30))
        last = max(it["at_min"] + (it.get("duration_min") or 20) for it in items)
        if msg.get("load", True):
            waits = float(msg.get("max_wait_min", 45.0)) * len(items) if msg.get("wait_for_normal", True) else 0.0
            horizon = max(float(msg.get("horizon_min", 0)), last + tail + waits + 5)
            await self.load({"scenario": msg.get("scenario", "nominal"), "horizon_min": horizon})
        t0 = self.status()["time_min"]
        obs = self.env.observation()
        baseline = {"throughput_target": obs["throughput_target_kmol_h"],
                    "setpoints": {k: v["setpoint"] for k, v in obs["controllers"].items()},
                    "modes": {k: v["mode"] for k, v in obs["controllers"].items()},
                    "auxiliary_commands": dict(obs["auxiliaries"])}
        self.campaign = {"name": name, "t0": t0, "tail_min": tail, "state": "running",
                         "restore": bool(msg.get("restore", True)), "baseline": baseline,
                         "wait_for_normal": bool(msg.get("wait_for_normal", True)),
                         "settle_min": float(msg.get("settle_min", 3.0)), "max_wait_min": float(msg.get("max_wait_min", 45.0)),
                         "started": datetime.now().isoformat(timespec="seconds"),
                         "items": [{**it, "due_min": t0 + it["at_min"], "status": "pending"} for it in items]}
        await self.broadcast({"type": "campaign", **self.campaign_status()})
        await self.notify(f"[campaign] {name}: {len(items)} injections scheduled from t={t0:.1f} min", "warn")
        if msg.get("run", True):
            self.set_running(True)
        return {"ok": True, "summary": f"campaign {name} started ({len(items)} injections)"}

    async def _campaign_due(self) -> None:
        c = self.campaign
        if not c or c["state"] != "running" or self.env is None:
            return
        now = 60.0 * self.env.t_h
        first_pending = next((it for it in c["items"] if it["status"] == "pending"), None)
        if (first_pending is not None and c["wait_for_normal"] and now + 1e-9 >= first_pending["due_min"]
                and now < first_pending["due_min"] + c["max_wait_min"] and not self._plant_settled(now, c["settle_min"])):
            # Hold the next injection until the plant is back to normal, so faults do not overlap.
            if not first_pending.get("waiting"):
                first_pending["waiting"] = True
                await self.notify(f"[campaign] holding {first_pending['label']} until the plant settles", "info")
                if c["restore"]:  # undo anything the agents changed during the recovery gap
                    await self.apply_action(SupervisoryAction(**c["baseline"], note="campaign_restore"),
                                            source="campaign restore")
                await self.broadcast({"type": "campaign", **self.campaign_status()})
            first_pending = None
        for it in c["items"]:
            if it["status"] == "pending" and it is first_pending and now + 1e-9 >= it["due_min"] and not self.env.done:
                late = now - it["due_min"]
                if late > 0.25:  # shift the rest of the schedule by the time spent waiting
                    for later in c["items"]:
                        if later is not it and later["status"] == "pending":
                            later["due_min"] += late
                it["waiting"] = False
                params = {k: v for k, v in it.items() if k not in ("at_min", "due_min", "status", "label", "name")}
                try:
                    await self._inject(params)
                    it.update(status="active", injected_min=now,
                              end_min=None if not it.get("duration_min") else now + float(it["duration_min"]))
                except Exception as exc:
                    it.update(status="failed", error=str(exc))
                await self.broadcast({"type": "campaign", **self.campaign_status()})
            elif it["status"] == "active" and it.get("end_min") is not None and now + 1e-9 >= it["end_min"]:
                it["status"] = "cleared"
                await self.notify(f"[campaign] {it['label']} cleared", "info")
                if c["restore"]:
                    # Like a shift operator after an incident: put back the settings the campaign
                    # started with and reset SIF latches, so each fault starts from the same point.
                    await self.apply_action(SupervisoryAction(**c["baseline"], note="campaign_restore"),
                                            source="campaign restore")
                    nxt = [x["due_min"] for x in c["items"] if x["status"] == "pending"]
                    c["recover_until"] = min(nxt, default=now + c["tail_min"])
                await self.broadcast({"type": "campaign", **self.campaign_status()})
        if (c["restore"] and now < c.get("recover_until", -1.0)
                and self.env.last_safety_result.latched_causes and not self._pending_reset_sif):
            # SIFs only clear once their variable is back inside the reset band, so keep asking.
            self._pending_reset_sif = True
        pending = [it for it in c["items"] if it["status"] == "pending"]
        ends = [it.get("end_min") or it.get("injected_min", 0.0) for it in c["items"]]
        if self.env.done or (not pending and now >= max(ends, default=now) + c["tail_min"]):
            await self.stop_campaign("episode ended" if self.env.done else "complete")

    def _plant_settled(self, now: float, settle_min: float) -> bool:
        """Monitoring agent reported normal for the last ``settle_min`` (True if agents are off)."""
        if not self.monitor:
            return True
        recent = [m for m in self.monitor if m["time_min"] >= now - settle_min - 1e-9]
        span_ok = self.monitor[0]["time_min"] <= now - settle_min + 1e-9
        return span_ok and bool(recent) and not any(m["fault"] for m in recent)

    async def stop_campaign(self, reason: str) -> dict:
        c = self.campaign
        if not c or c["state"] != "running":
            return {"ok": False, "summary": "no campaign running"}
        c["state"] = reason
        report = self.campaign_report()
        self.campaign_dir.mkdir(exist_ok=True)
        path = self.campaign_dir / f"{c['name']}_{datetime.now():%Y%m%d_%H%M%S}.json"
        path.write_text(json.dumps(jsonable({"campaign": c, "report": report, "agent_log": list(self.agent_log),
                                             "messages": list(self.messages)}), indent=1), encoding="utf-8")
        c["report_path"] = str(path)
        if reason == "complete":
            self.set_running(False)
        await self.broadcast({"type": "campaign", **self.campaign_status()})
        await self.notify(f"[campaign] {c['name']} {reason}; report saved to {path.name}", "warn")
        return {"ok": True, "summary": f"campaign {reason}", "report": report}

    def campaign_report(self) -> list[dict]:
        """Per injection: detection delay, first hypotheses, plan target, first agent action."""
        c = self.campaign or {"items": []}
        injected = [it for it in c["items"] if "injected_min" in it]
        rows = []
        for i, it in enumerate(injected):
            t0 = it["injected_min"]
            t1 = injected[i + 1]["injected_min"] if i + 1 < len(injected) else math.inf
            window = lambda e: t0 <= e.get("time_min", -1.0) < t1
            before = [m for m in self.monitor if m["time_min"] < t0]
            carry_over = bool(before) and before[-1]["fault"]  # plant already abnormal at injection
            mon = [m for m in self.monitor if window(m) and m["fault"]] if not carry_over else []
            acts = [a for a in self.agent_log if window(a) and a.get("stage") in ("applied", "pending")]
            plans = [a for a in self.agent_log if window(a) and a.get("stage") == "plan"]
            hyps = [h["fault"] for h in mon[0]["diagnosis"]["hypotheses"]] if mon else []
            rows.append({"fault": it["name"], "kind": it["kind"], "injected_min": t0, "carry_over": carry_over,
                         "detected": bool(mon), "detection_delay_min": mon[0]["time_min"] - t0 if mon else None,
                         "first_hypotheses": hyps[:3], "top1_correct": bool(hyps) and hyps[0] == it["name"],
                         "top3_correct": it["name"] in hyps[:3],
                         "plan_target": plans[0]["brief"].get("target_fault") if plans else None,
                         "first_action": (acts[0].get("plan") or {}).get("commands") if acts else None,
                         "action_delay_min": acts[0]["time_min"] - t0 if acts else None})
        return rows

    def campaign_status(self) -> dict:
        c = self.campaign
        if not c:
            return {"campaign": None}
        keys = ("label", "name", "kind", "due_min", "duration_min", "status", "injected_min", "end_min", "error", "waiting")
        return {"campaign": {"name": c["name"], "t0": c["t0"], "state": c["state"], "started": c["started"],
                             "report_path": c.get("report_path"),
                             "items": [{k: it.get(k) for k in keys} for it in c["items"]]}}

    # ------------------------------------------------------------ views
    def status(self) -> dict:
        env = self.env
        return {"running": self.running, "done": bool(env and env.done),
                "time_min": 60.0 * env.t_h if env else 0.0,
                "episode": env.spec.name if env else None,
                "episode_status": env.outcomes.state.status.value if env else None,
                "config": self.config, "tick_delay_ms": 1000 * self.tick_delay_s,
                "pace": {"every": self.pace_every, "sleep_s": self.pace_sleep_s},
                "hold_for_agents": self.hold_for_agents, "held": self.held}

    def _truth(self) -> dict:
        env, t = self.env, self.env.t_h
        events = []
        for ev in env.spec.scenario.events:
            phase = "active" if ev.active(t) else "pending" if t < ev.start_h else "done"
            events.append({"name": ev.name, "phase": phase, "start_min": 60 * ev.start_h,
                           "end_min": None if ev.end_h is None else 60 * ev.end_h})
        names = lambda xs: [x.name for x in xs]
        return {"schedule": events,
                "runtime": names(env.runtime_inputs.active_events(t)),
                "actuator": names(env.spec.actuator_faults.active_faults(t)),
                "sensor": names(env.spec.sensor_faults.active_faults(t)),
                "pump": names(env.spec.pump_faults.active_faults(t))}

    def snapshot(self) -> dict:
        env, plant = self.env, self.plant
        m, u, sp = env.last_measured, env.last_actual, env.controllers.sp
        yc, _ = plant.split_state(env.y)
        h2 = plant.cstr.h2_flow_components(yc, plant._cstr_inputs(u))
        t = 60.0 * env.t_h
        trend = dict(
            t=t,
            r_temp=m["cstr_temperature_K"], r_temp_sp=sp.cstr_temperature_K,
            r_press=m["cstr_pressure_bar"], r_press_sp=sp.cstr_pressure_bar,
            r_level=m["cstr_holdup_kmol"], r_level_sp=sp.cstr_holdup_kmol, r_x=m["cstr_x_acetone"],
            col_press=m["column_pressure_bar"], col_press_sp=sp.column_pressure_bar,
            top_temp=m["top_temperature_K"], top_temp_sp=sp.top_temperature_K,
            bottom_temp=m["bottom_temperature_K"], bottom_temp_sp=sp.bottom_temperature_K,
            rb_level=m["reboiler_holdup_kmol"], rb_level_sp=sp.reboiler_holdup_kmol,
            dr_level=m["drum_holdup_kmol"], dr_level_sp=sp.drum_holdup_kmol,
            dist_x=m["distillate_x_acetone"], btm_x=m["bottoms_x_acetone"],
            feed=u.fresh_ipa_feed, outflow=u.cstr_outflow, reflux=u.reflux_flow,
            distillate=u.distillate_flow, bottoms=u.bottoms_flow,
            heater=u.cstr_heater_factor, steam=u.steam_factor, cooling=u.condenser_cooling_valve,
            cool_eff=u.condenser_cooling_effectiveness, pcv=u.cstr_vent_valve, bdv=u.cstr_bdv_valve,
            psv=h2["psv_open_fraction"], h2=h2["total_kmol_h"], feed_temp=u.fresh_feed_temperature_K,
        )
        alarms = []
        for s in env.alarms.status.values():
            d = s.definition
            alarms.append({"id": d.alarm_id, "tag": d.tag, "state": s.state.value, "value": s.value,
                           "limit": d.limit, "unit": d.unit, "priority": d.priority,
                           "description": d.description})
        history = [{"time_min": e.time_min, "id": e.alarm_id, "transition": e.transition,
                    "priority": e.priority, "value": e.value, "description": e.description, "by": e.by}
                   for e in env.alarms.history[-60:][::-1]]
        return {
            **self.status(),
            "trend": trend,
            "measurements": {k: v for k, v in m.items() if not k.startswith("pump_")},
            "controllers": env.controllers.access_snapshot(m),
            "throughput_target": env.observation()["throughput_target_kmol_h"],
            "auxiliaries": dict(env.operator_auxiliary),
            "pumps": env.pumps.snapshot(env.t_h, env.spec.pump_faults),
            "alarms": alarms, "alarm_history": history,
            "sif_latched": list(env.last_safety_result.latched_causes),
            "plant_trip": bool(env.last_safety_result.plant_trip_latched),
            "last_action": env.last_action_result.summary,
            "truth": self._truth(),
        }

    def meta(self) -> dict:
        return {"scenarios": SCENARIOS,
                "loops": {k: {"sp_min": v.sp_min, "sp_max": v.sp_max, "sp_unit": v.sp_unit,
                              "mv_unit": v.mv_unit, "pv_tag": v.pv_tag}
                          for k, v in self.env.controllers.LOOP_SPECS.items()},
                "auxiliaries": {k: list(v) for k, v in EpisodeRunner.AUXILIARY_BOUNDS.items()},
                "throughput_bounds": list(EpisodeRunner.THROUGHPUT_BOUNDS),
                "pump_trains": {k: {"primary": v.primary_id, "spare": v.spare_id, "description": v.description}
                                for k, v in PUMP_TRAINS.items()},
                "pump_ids": list(PUMP_IDS),
                "injections": {"disturbances": DISTURBANCES,
                               "disturbance_steps": {k: disturbance_step(k, 1.0)[2].lstrip("+")
                                                     for k in DISTURBANCES},
                               "actuator_targets": ACTUATOR_TARGETS,
                               "actuator_modes": ["freeze", "capacity", "fixed", "stiction"],
                               "sensor_targets": SENSOR_TARGETS, "process_faults": PROCESS_FAULTS}}

    def hello(self) -> dict:
        from .campaigns import CAMPAIGNS, FAULT_LIBRARY
        out = {"api_version": API_VERSION,
               "meta": {**self.meta(), "campaigns": {k: v["description"] for k, v in CAMPAIGNS.items()},
                        "fault_library": sorted(FAULT_LIBRARY)},
               **self.campaign_status(), "snapshot": self.snapshot(), "trend": list(self.trend),
               "monitor": list(self.monitor), "agent_log": list(self.agent_log),
               "messages": list(self.messages)}
        for extra in self.hello_extras:
            out.update(extra())
        return jsonable(out)
